/**
 * The collection: stats, trait filters, a grid, and one token in detail.
 *
 * Modelled on how a marketplace presents a collection, with one rule that
 * changes what is shown: **every figure here is read from the chain or computed
 * from the contract.** No volume, no floor history, no holder counts pulled
 * from an indexer this project does not have. A stat that cannot be computed
 * honestly is left out rather than invented, which is why the bar is five
 * numbers and not twelve.
 *
 * Rarity comes from `rarity.js`, generated by walking `traitsOf` across the
 * whole supply. That function is pure, so the table is exact rather than
 * sampled, and a test fails if the art changes without it being regenerated.
 */

import { STRINGS } from "./i18n.js";
import { initChrome, prefersReduced } from "./chrome.js";
import { CHAIN, CONTRACTS, isDeployed } from "./config.js";
import { createDemo } from "./demo.js";
import { formatUnits } from "./abi.js";
import { RARITY, LAYERS, SUPPLY, TOKEN_TRAITS, rarestOf, percentOf } from "./rarity.js";
import * as chain from "./chain.js";

const chrome = initChrome(STRINGS, { prefix: "plinth" });
const $ = (id) => document.getElementById(id);
const t = (key) => (STRINGS[chrome.lang()] ?? STRINGS.en)[key] ?? key;

const locale = () => (chrome.lang() === "de" ? "de-DE" : "en-GB");
const pol = (wei) =>
  `${Number(formatUnits(wei)).toLocaleString(locale(), { maximumFractionDigits: 4 })} POL`;
const pct = (n) => `${n.toLocaleString(locale(), { maximumFractionDigits: 1 })}%`;

let state = createDemo();
let account = null;

/** Selected filters: layer index -> Set of values. */
const chosen = new Map();

// ------------------------------------------------------------------ backdrop

const ridges = [...document.querySelectorAll(".ridge")];
const reveals = [...document.querySelectorAll(".reveal")];

function onScroll() {
  const limit = window.innerHeight * 0.9;
  for (const el of reveals) {
    if (!el.classList.contains("is-in") && el.getBoundingClientRect().top < limit) {
      el.classList.add("is-in");
    }
  }
  if (prefersReduced) return;
  for (const ridge of ridges) {
    ridge.style.transform = `translateY(${window.scrollY * Number(ridge.dataset.depth ?? 0)}px)`;
  }
}

addEventListener("scroll", onScroll, { passive: true });
addEventListener("resize", onScroll, { passive: true });

// -------------------------------------------------------------------- traits

/**
 * The filter sidebar.
 *
 * Counts are of the whole supply, not of what is currently minted. A trait that
 * is 2.4% of 500 is 2.4% whether twelve tokens exist or all of them, and
 * recomputing it against the minted set would make the same cat look rarer on a
 * quiet day.
 */
function paintFilters() {
  const wrap = $("filter-groups");
  wrap.innerHTML = "";

  RARITY.forEach((group, layerIndex) => {
    const details = document.createElement("details");
    details.open = chosen.has(layerIndex);

    const summary = document.createElement("summary");
    summary.textContent = t(`layer.${layerIndex}`) ?? group.layer;

    const picked = chosen.get(layerIndex);
    if (picked?.size) {
      const badge = document.createElement("span");
      badge.className = "count";
      badge.textContent = String(picked.size);
      summary.append(badge);
    }

    details.append(summary);

    for (const { value, count, percent } of group.values) {
      const row = document.createElement("label");
      row.className = "trait-row";

      const box = document.createElement("input");
      box.type = "checkbox";
      box.checked = picked?.has(value) ?? false;
      box.addEventListener("change", () => {
        const set = chosen.get(layerIndex) ?? new Set();
        if (box.checked) set.add(value);
        else set.delete(value);

        if (set.size) chosen.set(layerIndex, set);
        else chosen.delete(layerIndex);

        paintFilters();
        paintGrid();
      });

      const name = document.createElement("span");
      name.className = "trait-name";
      name.textContent = value;

      const share = document.createElement("span");
      share.className = "trait-share";
      share.textContent = pct(percent);
      share.title = `${count} of ${SUPPLY}`;

      row.append(box, name, share);
      details.append(row);
    }

    wrap.append(details);
  });
}

/** Does this token pass every active filter? */
function matches(id) {
  const traits = TOKEN_TRAITS[String(id)];
  if (!traits) return false;

  for (const [layerIndex, values] of chosen) {
    if (!values.has(traits[layerIndex])) return false;
  }
  return true;
}

// ---------------------------------------------------------------------- grid

function artFor(token) {
  const wrap = document.createElement("div");
  wrap.className = "art";

  const img = document.createElement("img");
  img.loading = "lazy";
  img.alt = `Plinth Cat #${token.id}`;
  img.src = `data:image/svg+xml;base64,${btoa(unescape(encodeURIComponent(token.svg)))}`;

  wrap.append(img);
  return wrap;
}

function paintGrid() {
  const grid = $("grid");
  grid.innerHTML = "";

  let items = state.tokens.filter((tk) => matches(tk.id));

  const sort = $("sort").value;
  if (sort === "rare") items = [...items].sort((a, b) => rarestOf(a.id) - rarestOf(b.id));
  else if (sort === "price") {
    items = [...items].sort((a, b) => {
      if (a.listed !== b.listed) return a.listed ? -1 : 1;
      return a.price < b.price ? -1 : a.price > b.price ? 1 : 0;
    });
  } else items = [...items].sort((a, b) => Number(a.id - b.id));

  for (const token of items) {
    const card = document.createElement("button");
    card.type = "button";
    card.className = "item glass";
    card.addEventListener("click", () => openToken(token.id));

    const meta = document.createElement("div");
    meta.className = "meta";

    const row = document.createElement("div");
    row.className = "row";

    const id = document.createElement("span");
    id.className = "id";
    id.textContent = `#${token.id}`;

    const price = document.createElement("span");
    price.className = "price";
    price.textContent = token.listed ? pol(token.price) : t("item.unlisted");

    row.append(id, price);

    const rare = document.createElement("span");
    rare.className = "owner";
    rare.textContent = `${t("col.rarest")} ${pct(rarestOf(token.id))}`;

    meta.append(row, rare);
    card.append(artFor(token), meta);
    grid.append(card);
  }

  $("empty").hidden = items.length > 0;
  $("showing").textContent = t("col.showing")
    .replace("{n}", String(items.length))
    .replace("{total}", String(state.tokens.length));
}

// --------------------------------------------------------------- one token

function openToken(id) {
  const token = state.tokens.find((tk) => String(tk.id) === String(id));
  if (!token) return;

  $("t-art").innerHTML = "";
  $("t-art").append(artFor(token));
  $("t-name").textContent = `Plinth Cat #${token.id}`;
  $("t-owner").textContent = state.isDemo
    ? token.owner === state.address
      ? t("tok.you")
      : chain.shortAddress(token.owner)
    : chain.shortAddress(token.owner);

  $("t-price").textContent = token.listed ? pol(token.price) : t("item.unlisted");

  // Traits, each with what share of the supply carries it.
  const traits = $("t-traits");
  traits.innerHTML = "";

  const values = TOKEN_TRAITS[String(token.id)] ?? [];
  values.forEach((value, layerIndex) => {
    const cell = document.createElement("div");
    cell.className = "t-trait glass";

    const k = document.createElement("span");
    k.className = "k";
    k.textContent = t(`layer.${layerIndex}`) ?? LAYERS[layerIndex];

    const v = document.createElement("span");
    v.className = "v";
    v.textContent = value;

    const share = document.createElement("span");
    share.className = "share";
    const p = percentOf(layerIndex, value);
    share.textContent = t("tok.have").replace("{p}", pct(p));
    if (p <= 5) share.classList.add("is-rare");

    cell.append(k, v, share);
    traits.append(cell);
  });

  // Details, all of them checkable by anybody who wants to.
  const details = $("t-details");
  details.innerHTML = "";

  const rows = [
    [t("tok.contract"), CONTRACTS.collection ? chain.shortAddress(CONTRACTS.collection) : t("tok.demoOnly")],
    [t("tok.tokenId"), String(token.id)],
    [t("tok.standard"), "ERC-721"],
    [t("tok.chain"), CHAIN.name],
    [t("tok.royalty"), token.royalty],
  ];

  for (const [k, v] of rows) {
    if (!v) continue;
    const dt = document.createElement("dt");
    dt.textContent = k;
    const dd = document.createElement("dd");
    dd.textContent = v;
    details.append(dt, dd);
  }

  history.replaceState(null, "", `?id=${token.id}`);
  $("token").showModal();
}

$("token-close").addEventListener("click", () => $("token").close());
$("token").addEventListener("close", () => history.replaceState(null, "", location.pathname));
$("token").addEventListener("click", (event) => {
  // Clicking the backdrop closes it. The dialog element reports those clicks
  // as landing on itself rather than on any child.
  if (event.target === $("token")) $("token").close();
});

// -------------------------------------------------------------------- stats

function paintStats() {
  const minted = state.tokens.length;
  const listed = state.tokens.filter((tk) => tk.listed);
  const owners = new Set(state.tokens.map((tk) => tk.owner)).size;

  $("s-items").textContent = String(minted);
  $("s-supply").textContent = String(state.supply ?? SUPPLY);
  $("s-owners").textContent = String(owners);
  $("s-listed").textContent = String(listed.length);

  // Floor is the cheapest thing actually for sale. With nothing listed there is
  // no floor, and a dash says that better than a zero does.
  const floor = listed.reduce((low, tk) => (low === null || tk.price < low ? tk.price : low), null);
  $("s-floor").textContent = floor === null ? "—" : pol(floor);

  const creator = $("col-creator");
  creator.textContent = state.isDemo ? t("wallet.demoAccount") : chain.shortAddress(state.address);
  creator.href = state.isDemo ? "#" : `${CHAIN.explorer}/address/${state.address}`;

  // The avatar is token 1's artwork, so the collection is represented by
  // something the contract actually produced.
  const first = state.tokens[0];
  if (first) {
    $("col-avatar").innerHTML = "";
    $("col-avatar").append(artFor(first));
  }
}

// ------------------------------------------------------------------- wiring

$("clear").addEventListener("click", () => {
  chosen.clear();
  paintFilters();
  paintGrid();
});

$("sort").addEventListener("change", paintGrid);

$("connect").addEventListener("click", async () => {
  if (!chain.hasWallet() || !isDeployed()) return;
  try {
    account = await chain.connect();
    await loadLive();
  } catch {
    /* the marketplace page reports connection errors; here it just stays demo */
  }
});

chrome.onLangChange(() => {
  paintFilters();
  paintGrid();
  paintStats();
});

async function loadLive() {
  const minted = await chain.totalMinted();
  const supply = await chain.maxSupply();

  const tokens = [];
  for (let id = 1n; id <= minted; id++) {
    const listing = await chain.listingOf(id);
    const listed = listing.seller !== "0x0000000000000000000000000000000000000000";
    const meta = chain.metaFrom(await chain.tokenURI(id));

    tokens.push({
      id,
      svg: atob(meta.image.split(";base64,")[1]),
      royalty: meta.attributes?.find((a) => /royalty/i.test(a.trait_type))?.value ?? "",
      owner: listed ? listing.seller : await chain.ownerOf(id),
      listed,
      price: listing.price,
    });
  }

  state = { isDemo: false, address: account, supply, tokens };
  paintAll();
}

function paintAll() {
  paintStats();
  paintFilters();
  paintGrid();
  onScroll();

  // A shared link opens straight onto its token.
  const wanted = new URLSearchParams(location.search).get("id");
  if (wanted) openToken(wanted);
}

async function boot() {
  if (isDeployed() && chain.hasWallet()) {
    const existing = await chain.currentAccount();
    if (existing && (await chain.currentChainId()) === CHAIN.hex) {
      account = existing;
      try {
        await loadLive();
        return;
      } catch {
        /* fall through to the demo rather than showing a broken collection */
      }
    }
  }
  paintAll();
}

boot();
